sections.text:
Customize multiple abbreviations at once:

g2p = get_g2p("en-us")

# Remove unwanted abbreviations
for abbr in ["Dr.", "Mr.", "Mrs.", "Ms."]:
    g2p.remove_abbreviation(abbr)

# Add custom ones
custom_abbrevs = {
    "Tech.": "Technology",
    "Corp.": "Corporation",
    "Dept.": "Department"
}

for abbr, expansion in custom_abbrevs.items():
    g2p.add_abbreviation(abbr, expansion)

